#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — bring up the HEY gateway, end to end. Safe to re-run: stages that
# are already done (binaries built, key made, droplet up, signed in) offer to skip.
# ──────────────────────────────────────────────────────────────────────────

# The whole body is one block, so bash parses all of it before running any: editing this
# file while a run is in progress can't make the run jump into the middle of a line.
{
TOTAL_STAGES=10

here="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
root="$(cd -- "${here}/.." && pwd)"
cd "$root"
# Non-secret choices only. Tokens and auth keys are never written anywhere.
ENV_FILE="${root}/.env.wizard"

# shellcheck source=scripts/gateway.env.sh
source "${here}/gateway.env.sh"

OPENCLAW_ADMIN="${OPENCLAW_ADMIN:-openclaw-admin@openclaw-gateway}"
OPENCLAW_SSH_KEY="${OPENCLAW_SSH_KEY:-$HOME/.ssh/openclaw_admin}"
HEY_CLI_FORK="${HEY_CLI_FORK:-$HOME/personal/forks/hey-cli}"

oc_ssh() { ssh -T -i "$OPENCLAW_SSH_KEY" -o IdentitiesOnly=yes -o ConnectTimeout=10 "$OPENCLAW_ADMIN" "$@"; }
oc_scp() { scp -i "$OPENCLAW_SSH_KEY" -o IdentitiesOnly=yes "$@"; }
gw_quiet() { ssh -T "${gateway_ssh_opts[@]}" -o BatchMode=yes -o ConnectTimeout=5 "$HEY_GATEWAY_ADMIN" "$@"; }

fail() { printf '\n  %s✗ %s%s\n\n' "$RED" "$1" "$RESET"; exit 1; }

# attempt "description" cmd... — run a command; on failure, offer to retry or stop.
attempt() {
  local what="$1"; shift
  while true; do
    printf '  %s$%s %s\n' "$DIM" "$RESET" "$*"
    if "$@"; then return 0; fi
    warn "$what failed."
    confirm "Retry?" || fail "Stopped at: $what. Fix it and re-run this wizard; finished stages can be skipped."
  done
}

banner "HEY gateway bring-up"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Preflight"
say "Checking tools and that both machines are reachable over Tailscale."
for tool in terraform ssh scp go curl; do
  command -v "$tool" >/dev/null 2>&1 || fail "missing required command: $tool"
done
note "tools: terraform ssh scp go curl — ok"
[[ -f "$HEY_GATEWAY_SSH_KEY" && -f "${HEY_GATEWAY_SSH_KEY}.pub" ]] \
  || fail "admin key not found: $HEY_GATEWAY_SSH_KEY(.pub). Set HEY_GATEWAY_SSH_KEY to use another."
note "admin key: $HEY_GATEWAY_SSH_KEY — ok"
[[ -d "$HEY_CLI_FORK" ]] || fail "hey-cli fork not found at $HEY_CLI_FORK (set HEY_CLI_FORK)"
note "hey-cli fork: $HEY_CLI_FORK — ok"
attempt "reaching the OpenClaw gateway ($OPENCLAW_ADMIN)" oc_ssh true
note "OpenClaw gateway: reachable"
attempt "terraform init" terraform -chdir=infra init -input=false >/dev/null
note "terraform: initialized"
pause "Continue?"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Build the binaries"
say "hey-gordy is what the agent runs; the full hey is only used to sign in, then deleted."
if [[ -f "${HEY_CLI_BIN_DIR}/hey-gordy-linux-amd64" && -f "${HEY_CLI_BIN_DIR}/hey-linux-amd64" ]]; then
  note "Found existing builds in ${HEY_CLI_BIN_DIR}:"
  (cd "$HEY_CLI_BIN_DIR" && ls -l --time-style=+%Y-%m-%d\ %H:%M hey-gordy-linux-amd64 hey-linux-amd64 | awk '{print "    " $6, $7, $8}')
  if confirm "Rebuild from the fork's current code?"; then
    attempt "building" "${HEY_CLI_FORK}/scripts/build-hey-gordy.sh"
  fi
else
  attempt "building" "${HEY_CLI_FORK}/scripts/build-hey-gordy.sh"
fi
pause "Continue?"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Gordy's SSH key (on the OpenClaw gateway)"
say "The agent logs in to the HEY gateway with its own key, which never leaves the OpenClaw gateway."
agent_key_cmd='test -f ~/.ssh/hey_gateway_gordy || ssh-keygen -q -t ed25519 -a 64 -N "" -C gordy@openclaw-gateway -f ~/.ssh/hey_gateway_gordy; cat ~/.ssh/hey_gateway_gordy.pub'
AGENT_PUBKEY="$(oc_ssh "$agent_key_cmd")" || fail "could not create or read ~/.ssh/hey_gateway_gordy on the OpenClaw gateway"
[[ "$AGENT_PUBKEY" == ssh-ed25519\ * ]] || fail "unexpected public key: $AGENT_PUBKEY"
note "agent key: ${AGENT_PUBKEY:0:40}…"
pause "Continue?"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Is there a HEY gateway (hey-gateway) already?"
CREATE=yes
# An empty state still exits 0 (with a "No outputs found" warning), so only a real id counts.
droplet_id="$(terraform -chdir=infra output -raw droplet_id 2>/dev/null || true)"
if [[ "$droplet_id" =~ ^[0-9]+$ ]]; then
  say "Terraform already manages a hey-gateway droplet (id ${droplet_id})."
  say "The next three stages create one, so they will be skipped."
  note "For a fresh gateway instead: Ctrl-C, run make destroy, and re-run this wizard."
  CREATE=no
else
  say "No hey-gateway in this directory's Terraform state: the next stages create one."
  note "This is the new HEY droplet only. The OpenClaw gateway has its own state and is untouched."
fi
pause "Continue?"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Tailscale: clear the old machine, make an auth key"
if [[ "$CREATE" == no ]]; then
  note "Skipped: the gateway already exists."
else
  say "First, a gateway from an earlier bring-up must be gone from your tailnet, or the"
  say "new one enrolls as hey-gateway-1 and the agent's SSH config points at nothing."
  open_url "https://login.tailscale.com/admin/machines"
  step "Look for a machine named hey-gateway. If it's there: ••• menu → Remove."
  pause "Done (or there wasn't one)?"
  printf '\n'
  say "Now a one-off key for the new droplet to join with."
  open_url "https://login.tailscale.com/admin/settings/keys"
  step "Click 'Generate auth key…'."
  step "Leave Reusable and Ephemeral off."
  step "Turn on Tags and choose tag:openclaw (the tag the OpenClaw gateway uses)."
  step "Generate, then copy the key (it starts tskey-auth-)."
  while true; do
    ask_secret TF_VAR_tailscale_auth_key "Paste the auth key (hidden, never saved):"
    [[ "$TF_VAR_tailscale_auth_key" == tskey-auth-* ]] && break
    warn "That doesn't start with tskey-auth-; try again."
  done
  export TF_VAR_tailscale_auth_key
  printf '  %s✓ captured%s (kept in memory for this run only)\n' "$GREEN" "$RESET"
fi
pause "Continue?"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "DigitalOcean API token"
if [[ "$CREATE" == no ]]; then
  note "Skipped: the gateway already exists."
elif [[ -n "${DIGITALOCEAN_TOKEN:-}" ]]; then
  note "Using DIGITALOCEAN_TOKEN from your environment."
else
  open_url "https://cloud.digitalocean.com/account/api/tokens"
  step "Use an existing token you still have, or 'Generate New Token' with a short expiry."
  note "It needs to create droplets, VPCs, firewalls, tags, SSH keys and projects."
  while true; do
    ask_secret DIGITALOCEAN_TOKEN "Paste the token (hidden, never saved):"
    [[ -n "$DIGITALOCEAN_TOKEN" ]] && break
  done
  printf '  %s✓ captured%s (kept in memory for this run only)\n' "$GREEN" "$RESET"
fi
export DIGITALOCEAN_TOKEN="${DIGITALOCEAN_TOKEN:-}"
pause "Continue?"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Create the droplet"
if [[ "$CREATE" == no ]]; then
  note "Skipped: the gateway already exists."
  pause "Continue?"
else
  export TF_VAR_ssh_public_key TF_VAR_agent_ssh_public_key
  TF_VAR_ssh_public_key="$(< "${HEY_GATEWAY_SSH_KEY}.pub")"
  TF_VAR_agent_ssh_public_key="$AGENT_PUBKEY"
  attempt "terraform init" make --no-print-directory init
  attempt "terraform plan" make --no-print-directory plan
  printf '\n'
  say "Read the plan above: only additions (0 to change, 0 to destroy), all named hey-gateway…"
  confirm "Apply it and create the droplet?" || fail "Not applied. Re-run when ready."
  attempt "terraform apply" make --no-print-directory apply
  # A new droplet has a new host key; forget the old one.
  rm -f -- "$HEY_GATEWAY_KNOWN_HOSTS"
  printf '  %s✓ created%s\n' "$GREEN" "$RESET"
  pause "Continue?"
fi

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Wait for bootstrap, then install hey-gordy"
say "Waiting for the droplet to join the tailnet (package upgrades run first; allow ~5 min)."
for i in $(seq 1 90); do
  if gw_quiet true 2>/dev/null; then break; fi
  (( i == 90 )) && fail "hey-gateway never became reachable. Check the DigitalOcean console (Access → Droplet Console) and: sudo cloud-init status --long"
  printf '\r  %swaiting… %ss%s ' "$DIM" "$((i * 10))" "$RESET"
  sleep 10
done
printf '\r  %s✓ reachable%s              \n' "$GREEN" "$RESET"
attempt "waiting for cloud-init" gw_quiet 'sudo cloud-init status --wait >/dev/null; sudo test -f /var/lib/hey-gateway-bootstrap-complete'
note "bootstrap: complete"
attempt "installing hey-gordy" ./scripts/deploy.sh
pause "Continue?"

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Sign in to HEY"
if gw_quiet 'sudo -n -H -u hey /usr/local/libexec/hey-gordy --json account list' >/dev/null 2>&1 \
  && ! confirm "The gateway is already signed in. Sign in again anyway?"; then
  note "Kept the existing sign-in."
else
  login_log="$(mktemp)"
  ./scripts/login.sh </dev/null >"$login_log" 2>&1 &
  login_pid=$!
  auth_url=""
  for _ in $(seq 1 60); do
    auth_url="$(tr -d '\r' < "$login_log" | grep -o 'https://app\.hey\.com/oauth/authorizations/new?[^[:space:]]*' | head -n1 || true)"
    [[ -n "$auth_url" ]] && break
    kill -0 "$login_pid" 2>/dev/null || break
    sleep 1
  done
  if [[ -z "$auth_url" ]]; then
    cat "$login_log"
    fail "the sign-in never printed a URL (output above)"
  fi
  open_url "$auth_url"
  step "Sign in to HEY in the browser tab that just opened and approve access."
  step "HEY then sends the browser to http://127.0.0.1:…/callback?… — the gateway's"
  step "own address, not yours — so that page fails to load. That's expected."
  step "Copy the whole URL from the address bar."
  while true; do
    ask CALLBACK_URL "Paste the callback URL:"
    [[ "$CALLBACK_URL" =~ ^http://127\.0\.0\.1:[0-9]+/callback\? ]] && break
    warn "That isn't the http://127.0.0.1:<port>/callback?… URL; try again."
  done
  attempt "handing the sign-in to the gateway" ./scripts/login.sh callback "$CALLBACK_URL"
  if wait "$login_pid"; then
    printf '  %s✓ signed in%s\n' "$GREEN" "$RESET"
    tr -d '\r' < "$login_log" | sed -n '/Checking the restricted binary/,$p' | sed 's/^/    /'
  else
    tr -d '\r' < "$login_log" | tail -n 15 | sed 's/^/    /'
    rm -f -- "$login_log"
    fail "sign-in failed (output above). Re-run the wizard; finished stages can be skipped."
  fi
  rm -f -- "$login_log"
fi
pause "Continue?"

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Set up the OpenClaw gateway"
say "Installing the hey wrapper, the SSH host entry and the agent's skill."
attempt "creating directories" oc_ssh 'mkdir -p ~/.local/bin ~/.ssh && chmod 700 ~/.ssh'
attempt "copying the hey wrapper" oc_scp client/hey "${OPENCLAW_ADMIN}:.local/bin/hey"
attempt "marking it executable" oc_ssh 'chmod 755 ~/.local/bin/hey'
if oc_ssh 'grep -qx "Host hey-gateway" ~/.ssh/config 2>/dev/null'; then
  note "~/.ssh/config already has a hey-gateway entry; left as is."
else
  attempt "adding the SSH host entry" oc_ssh '{ echo; cat; } >> ~/.ssh/config && chmod 600 ~/.ssh/config' < client/ssh_config
fi
printf '\n'
# Gordy is OpenClaw's default agent ("main"); its workspace skills folder has the highest
# precedence. Override OPENCLAW_SKILL_DIR for another agent's workspace.
OPENCLAW_SKILL_DIR="${OPENCLAW_SKILL_DIR:-~/.openclaw/workspace/skills/hey}"
attempt "installing the skill in $OPENCLAW_SKILL_DIR" oc_ssh "mkdir -p $OPENCLAW_SKILL_DIR && cat > $OPENCLAW_SKILL_DIR/SKILL.md" < client/skill/SKILL.md
if oc_ssh '~/.local/bin/openclaw skills info hey' 2>/dev/null | sed 's/^/    /'; then
  note "OpenClaw sees the hey skill. A session already running may need a new one to pick it up."
else
  warn "openclaw skills info hey didn't find it; check with: openclaw skills list"
fi
printf '\n'
say "End-to-end check: the OpenClaw gateway reads your Imbox through the HEY gateway."
attempt "running hey box view imbox from the OpenClaw gateway" oc_ssh '~/.local/bin/hey box view imbox --limit 5 --markdown'
pause "Looks right?"

finish
note "Rebuild any time: make destroy, then make bring-up."
note "Update hey-gordy only: rebuild in the fork, then make deploy."
printf '\n'
exit 0
}
